import re

def get_total_from_file(filepath):
    with open(filepath, 'r') as f:
        lines = f.readlines()
    # Find the line that ends with 'TOTAL: <number>'
    for line in reversed(lines):
        match = re.search(r'TOTAL:\s*(\d+)$', line.strip())
        if match:
            return int(match.group(1))
    return 0

